import { Component, computed, signal } from '@angular/core';

interface Tarea { id: number; titulo: string; hecha: boolean; }

@Component({
  selector: 'app-tablero',
  template: `
    <p>{{ pendientes() }} pendientes de {{ tareas().length }}</p>
    <button (click)="agregar('Revisar PR')">Agregar</button>
  `,
})
export class Tablero {
  readonly tareas = signal<Tarea[]>([]);
  readonly pendientes = computed(() => this.tareas().filter(t => !t.hecha).length);

  agregar(titulo: string) {
    this.tareas.update(lista => [...lista, { id: Date.now(), titulo, hecha: false }]);
  }
}

