import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  template: `
    <h1>Tareas: {{ cantidad }}</h1>
    <button (click)="agregar()">Agregar tarea</button>
    <ul>
      @for (t of tareas; track $index) {
        <li>{{ t }}</li>
      }
    </ul>
  `,
})
export class App {
  // TODO: convertí esto a signals
  tareas: string[] = ['Configurar CI'];
  cantidad = this.tareas.length;

  agregar() {
    this.tareas.push('Tarea ' + (this.tareas.length + 1));
  }
}

